WITH web_events_by_session AS (SELECT session_id, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range, MAX(duration_sec) AS max_duration_sec FROM web_events WHERE session_id IN (10, 30) GROUP BY session_id) SELECT s.id, s.browser, s.device, webs.duration_sec_range, webs.max_duration_sec FROM sessions s INNER JOIN web_events_by_session webs ON s.id = webs.session_id WHERE webs.duration_sec_range > 63;
